import { createStore } from 'vuex';
export const store = createStore({
  state: () => ({ count: 0 }),
  getters: { doubled: state => state.count * 2 },
  mutations: { add(state, amount) { state.count += amount; } },
  actions: { addOne({ commit }) { commit('add', 1); } }
});
store.dispatch('addOne');
console.log(store.state.count, store.getters.doubled); // 1 2
