type Product = Readonly<{ name: string; priceCents: number }>;
function parseProduct(value: unknown): Product | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const v = value as Record<string, unknown>;
  if (typeof v.name !== 'string' || typeof v.priceCents !== 'number' ||
      !Number.isSafeInteger(v.priceCents) || v.priceCents < 0) return null;
  return { name: v.name, priceCents: v.priceCents };
}
function ProductCard({ product }: { product: Product }) {
  return <p>{product.name}：{(product.priceCents / 100).toFixed(2)} 元</p>;
}

import { useEffect, useState } from 'react';
export default function WidthInfo() {
  const [width, setWidth] = useState(null);
  useEffect(() => {
    const update = () => setWidth(window.innerWidth);
    update();
    window.addEventListener('resize', update);
    return () => window.removeEventListener('resize', update);
  }, []);
  return <p>窗口宽度：{width === null ? '等待浏览器信息' : width}</p>;
}

