import { useEffect, useState } from 'react';
export default function MessagePanel({ topic, subscribe }) {
  const [message, setMessage] = useState('');
  useEffect(() => {
    let active = true;
    setMessage('');
    const stop = subscribe(topic, value => { if (active) setMessage(String(value)); });
    return () => { active = false; stop(); };
  }, [topic, subscribe]);
  return <section><h2>{topic}</h2><p>{message || '等待消息'}</p></section>;
}

