function cartReducer(state = { count: 0 }, action) {
  switch (action.type) {
    case 'cart/add': return { ...state, count: state.count + action.amount };
    case 'cart/clear': return { ...state, count: 0 };
    default: return state;
  }
}
const before = { count: 1 };
const after = cartReducer(before, { type: 'cart/add', amount: 2 });
console.log(before.count, after.count, before === after); // 1 3 false

import { useState } from 'react';
function Row({ item }) {
  const [draft, setDraft] = useState(item.title);
  return <label>{item.id}<input value={draft} onChange={e => setDraft(e.target.value)} /></label>;
}
export default function CourseList() {
  const [items, setItems] = useState([{ id: 'a', title: 'HTML' }, { id: 'b', title: 'CSS' }]);
  return <section><button onClick={() => setItems(xs => [...xs].reverse())}>反转</button>
    {items.map(item => <Row key={item.id} item={item} />)}
  </section>;
}

import { useEffect, useState } from 'react';
const KEY = 'course-draft-v1';
function readDraft() {
  try {
    const saved = JSON.parse(localStorage.getItem(KEY) || 'null');
    return saved?.version === 1 && typeof saved.text === 'string' ? saved.text : '';
  } catch { return ''; }
}
export default function DraftEditor() {
  const [draft, setDraft] = useState(readDraft);
  const [error, setError] = useState('');
  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify({ version: 1, text: draft })); setError(''); }
    catch { setError('保存失败，请复制草稿备份。'); }
  }, [draft]);
  return <section><textarea aria-label="课程笔记" value={draft} onChange={e => setDraft(e.target.value)} />
    {error && <p role="alert">{error}</p>}</section>;
}
